.venv/bin/python -c "from OCP.STEPControl import STEPControl_Reader; from OCP.TopExp import TopExp_Explorer; from OCP.TopAbs import TopAbs_FACE; from OCP.TopoDS import TopoDS; from OCP.BRepAdaptor import BRepAdaptor_Surface; from OCP.Bnd import Bnd_Box; from OCP.BRepBndLib import BRepBndLib; r=STEPControl_Reader(); r.ReadFile('job/part.step'); r.TransferRoots(); s=r.OneShape(); b=Bnd_Box(); BRepBndLib.Add_s(s,b); print('BOUNDS inches',tuple(round(v/25.4,6) for v in b.Get())); e=TopExp_Explorer(s,TopAbs_FACE)
while e.More():
 a=BRepAdaptor_Surface(TopoDS.Face_s(e.Current())); t=str(a.GetType()); g=a.Cylinder() if 'Cylinder' in t else a.Plane() if 'Plane' in t else None
 if g: print(t,'origin inches',tuple(round(v/25.4,6) for v in g.Location().Coord()),'radius inches',round(g.Radius()/25.4,6) if 'Cylinder' in t else '-', 'axis',g.Axis().Direction().Coord())
 e.Next()"

